/**
 * Validate a date string in YYYY-MM-DD format (UTC).
 * @param {string} dateString
 * @returns {boolean}
 */
export function isValidDate(dateString) {
  if (typeof dateString !== 'string') return false;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateString)) return false;

  const date = new Date(dateString + 'T00:00:00Z');
  if (isNaN(date.getTime())) return false;

  const [year, month, day] = dateString.split('-').map(Number);
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/**
 * Add n days to a date string (YYYY-MM-DD, UTC).
 * @param {string} dateString
 * @param {number} days
 * @returns {string}
 */
export function addDays(dateString, days) {
  const date = new Date(dateString + 'T00:00:00Z');
  date.setUTCDate(date.getUTCDate() + days);
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, '0');
  const day = String(date.getUTCDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/**
 * Calculate the difference in whole days between two dates (b minus a, in UTC).
 * @param {string} dateStringA
 * @param {string} dateStringB
 * @returns {number}
 */
export function daysBetween(dateStringA, dateStringB) {
  const dateA = new Date(dateStringA + 'T00:00:00Z');
  const dateB = new Date(dateStringB + 'T00:00:00Z');
  const diffMs = dateB.getTime() - dateA.getTime();
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

/**
 * Get the last day of the month for a given date (YYYY-MM-DD, UTC).
 * @param {string} dateString
 * @returns {string}
 */
export function lastDayOfMonth(dateString) {
  const date = new Date(dateString + 'T00:00:00Z');
  const year = date.getUTCFullYear();
  const month = date.getUTCMonth();
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  const dayStr = String(lastDay).padStart(2, '0');
  const monthStr = String(month + 1).padStart(2, '0');
  return `${year}-${monthStr}-${dayStr}`;
}
